const mc = (question, options, correctAnswer, explanation, format = 'Multiple choice') => ({
  question, options, correctAnswer, explanation, format
});

const written = (question, rubric, sampleAnswer, explanation, format = 'Write a prompt') => ({
  type: 'text', format, question, rubric, sampleAnswer, explanation
});

